import re, os, sys, subprocess, json

ROOT = "."
DIRS = ["drivers/net", "drivers/staging", "drivers/atm", "drivers/tty", "drivers/usb", "net"]

# 1. collect files with tasklet registration or napi registration
pat_tasklet = re.compile(r'(?:tasklet_init|tasklet_setup)\s*\(\s*&?([^,\s]+)\s*,\s*([A-Za-z_0-9]+)')
pat_napi = re.compile(r'netif_napi_add(?:_dev)?\s*\(\s*[^;]*?,\s*([A-Za-z_0-9\.\->]+)\s*,\s*([A-Za-z_0-9]+)')

files = set()
out = subprocess.run(["grep","-rl","-e","tasklet_init","-e","tasklet_setup","-e","netif_napi_add","--include=*.c"]+DIRS, capture_output=True, text=True)
for f in out.stdout.split():
    files.add(f)

def func_body(src, name):
    # find definition of function name, return body text
    m = re.search(r'(?:^|\n)[A-Za-z_0-9 \*\t]+\b'+re.escape(name)+r'\s*\([^;{]*?\)\s*\n?\{', src)
    if not m:
        return None, None
    start = m.start()
    i = src.index('{', m.start())
    depth = 0
    for j in range(i, len(src)):
        if src[j] == '{': depth += 1
        elif src[j] == '}':
            depth -= 1
            if depth == 0:
                return src[i:j+1], src[:i].count('\n')+1
    return None, None

lock_re = re.compile(r'spin_(?:lock|unlock)(?:_bh|_irq|_irqsave|_irqrestore)?\s*\(\s*([^);]+?)\s*[,)]')

def locks_in(body, only_plain=False):
    res = []
    for m in re.finditer(r'spin_lock(?:_bh|_irqsave|_irq)?(?:_nested)?\s*\(\s*([^);]+?)\s*[,)]', body):
        variant = m.group(0).split('(')[0]
        res.append((m.group(1).strip(), variant))
    return res

results = []
for f in sorted(files):
    try:
        src = open(f, errors='replace').read()
    except Exception:
        continue
    callbacks = []
    for m in pat_tasklet.finditer(src):
        cb = m.group(2)
        if cb and cb not in ('NULL',):
            callbacks.append((cb, 'tasklet'))
    for m in pat_napi.finditer(src):
        cb = m.group(2)
        if cb:
            callbacks.append((cb, 'napi'))
    for cb, kind in set(callbacks):
        body, line = func_body(src, cb)
        if not body:
            continue
        for lockexpr, variant in locks_in(body):
            # softirq side lock; now find same lock in other functions of this file with any spin_lock variant
            if variant != 'spin_lock':
                continue  # only plain-locked softirq side is interesting (or any variant, but plain is the classic)
            # find all plain spin_lock sites on the same expr in file
            sites = []
            for m in re.finditer(re.escape('spin_lock('), src):
                ln = src[:m.start()].count('\n')+1
                # capture the lock expr
                mm = re.match(r'spin_lock\(\s*([^);]+?)\s*[,)]', src[m.start():])
                if mm and mm.group(1).strip() == lockexpr:
                    sites.append(ln)
            cblines = []
            for m in re.finditer(re.escape('spin_lock'), src):
                pass
            if len(sites) > 1:
                results.append({"file": f, "cb": cb, "kind": kind, "defline": line, "lock": lockexpr, "plain_sites": sites})

for r in results:
    print(json.dumps(r))
